    use TracerAwareTrait;

    public function __construct(
        private readonly DcrInitialAccessTokenListUsecase $listUsecase,
        private readonly AesCypherService $cypherService,
    ) {
    }
    #[OA\Get(
        path: "/api/access/dcr-initial-access-tokens",
        tags: ["Dcr initial access token"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/DcrInitialAccessTokenApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Dcr initial access token");
        $span = $this->startSpan("List Dcr initial access token");
        try {
            $params = $request->getQueryParams();
            $limit = filter_var($params['limit'] ?? 100, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
            if ($limit === false) {
                $response->getBody()->write('{"error":"invalid_limit"}');
                return $response->withStatus(400)->withHeader('Content-Type', 'application/json');
            }
            $filter = new DcrInitialAccessTokenFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                tokenHash: $params['token-hash'] ?? null,
                description: $params['description'] ?? null,
                tenant: isset($params['tenant']) ? new TenantRef($params['tenant']) : null,
                tenants: isset($params['tenants']) ? explode(",", $params['tenants']) : null,
            );
            $cursor = new DcrInitialAccessTokenCursor(
                limit: $limit,
                sinceUid: $params['since-uid'] ?? null,
                sinceDescription: $params['since-description'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (DcrInitialAccessTokenAttributes $item): DcrInitialAccessTokenApiDTO => $this->mapDcrInitialAccessToken($request, $item), $result->values())];
            $nextLink = $result->hasNext() ? $this->nextLink($result->cursor(), $params) : null;
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for Dcr initial access token");
        $span = $this->startSpan("Extract order for Dcr initial access token");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'description-asc') {
                    $mapped[] = 'descriptionAsc';
                }
                if ($ord === 'description-desc') {
                    $mapped[] = 'descriptionDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?DcrInitialAccessTokenCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Dcr initial access token");
        $span = $this->startSpan("Generic allow for Dcr initial access token");
        try {
            if (!$value) {
                return null;
            }
            $link = array_merge($params, [
                        'since-uid' => $value->sinceUid(),
                        'since-description' => $value->sinceDescription(),
                    ]);
            return http_build_query(array_filter($link, fn (mixed $item): bool => null !== $item));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapDcrInitialAccessToken(ServerRequestInterface $request, DcrInitialAccessTokenAttributes $value): DcrInitialAccessTokenApiDTO
    {
        $this->logDebug("Map entity to output dto for Dcr initial access token");
        $span = $this->startSpan("Map entity to output dto for Dcr initial access token");
        try {
            $tenant = $value->getTenant();
            $dto = new DcrInitialAccessTokenApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->description = $value->getDescription();
            $dto->tokenHash = '******';
            $dto->expiresAt = $value->getExpiresAt()?->format(DateTime::ATOM);
            $dto->maxUses = $value->getMaxUses();
            $dto->uses = $value->getUses();
            $dto->allowedGrantTypes = $value->getAllowedGrantTypes();
            $dto->revokedAt = $value->getRevokedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
